import {hasSensitive} from './admin-permissions.mjs';
export function createStockCorrectionViews({api,h,showPanel,getUser,writable,notify,localTime}){
 const allowed=()=>hasSensitive(getUser(),'finance')&&hasSensitive(getUser(),'resources');
 async function detail(id,offset=0){await showPanel('商品单据纠错与数量联动',async signal=>{const s=await api.stockCorrection(id,offset,signal),d=s.document;
  return `<div class="dialog-header"><h2>商品单据纠错</h2><button class="icon-button" data-stock-correction-close aria-label="关闭商品纠错">×</button></div><p>${h(d.businessDate)} · ${h(d.sourceReference||'原商品单据')} · ${d.status==='void'?'已作废':'有效'} · 更正第 ${d.version} 版</p><button class="text-button" data-product-stock-document="${h(id)}">查看原单据与原登记余额</button>${writable&&allowed()&&d.status==='active'?`<button class="secondary" data-stock-correction-edit="${h(id)}">更正数量、日期或业务归属</button><button class="text-button" data-stock-correction-void="${h(id)}">作废错误单据</button>`:''}`+
   s.lines.map(l=>`<article class="observation"><b>${h(l.snapshot.skuCode)} · ${h(l.snapshot.name)}</b><p>${d.status==='void'?'作废前单据数量':'当前有效单据数量'} ${l.quantity} ${h(l.snapshot.unit)} · 库存来源 ${h(l.snapshot.storeName||'公共库存')} · 业务店铺 ${h(l.snapshot.businessStoreName||'未指定')}</p><p>此归属现存 ${l.currentQuantity} · 商品总现存 ${l.itemQuantity}</p>${l.quantityLocked?'<p class="muted">后续已有盘点／人工纠错，数量不再直接冲回，需核对实物及已有调整。</p>':''}</article>`).join('')+(d.operation==='inbound'?`<button class="secondary" data-product-purchase="${h(id)}">核对原入库采购成本</button><p class="muted">入库数量或业务事实更正后，原成本版本继续保留，重新确认前不冒充有效成本。</p>`:'')+
   '<h3>更正历史</h3>'+s.history.rows.map(v=>`<article class="observation"><b>第 ${v.version} 版 · ${v.status==='void'?'已作废':'有效'} · ${h(v.businessDate)}</b><p>${h(v.sourceReference)}</p>${v.lines.map(l=>`<p>${h(l.snapshot.skuCode)} · 原有效数量 ${l.previousQuantity} → ${v.status==='void'?0:l.quantity} · 追加数量差额 ${l.adjustment>0?'+':''}${l.adjustment} · 归属余额 ${l.balanceBefore} → ${l.balanceAfter}</p>`).join('')}<p class="preserve-text">${h(v.reason)}</p><small>${h(v.actor)} · ${h(localTime(v.createdAt))}</small></article>`).join('')+(!s.history.rows.length?'<p class="muted">暂无更正，原数量及业务事实沿用原单。</p>':'')+`<div class="pager"><button class="secondary" data-stock-correction="${h(id)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${s.history.total} 条更正</span><button class="secondary" data-stock-correction="${h(id)}" data-offset="${offset+50}" ${offset+50>=s.history.total?'disabled':''}>下一页</button></div>`;
 });}
 document.addEventListener('click',e=>{if(e.target.closest('[data-stock-correction-close]'))document.querySelector('#cloud-detail').close();const b=e.target.closest('[data-stock-correction]');if(b)detail(b.dataset.stockCorrection,Number(b.dataset.offset||0)).catch(e=>notify(e.message));});return {detail};
}
